(() => {
 'use strict';
 const $=s=>document.querySelector(s), stage=$('#stage'), controls=$('#controls');
 const tool=new URLSearchParams(location.search).get('tool')||'motion';
 const titles={motion:['MOTION / 12.23.24','同一动作，不同节奏。','点击重播，比较直接移动与柔和过渡。'],paper:['PAPER.JS / 0.12.18','镜头先有路，再有速度。','拖动曲率滑杆，观察路径和观察点；导出可编辑 SVG。'],grapes:['GRAPESJS / 0.22.13','把内容，编排成页面。','双击文字修改；拖入内容块。完成后导出 HTML 保存。'],two:['TWO.JS / 0.8.23','从散落，到清晰。','拖动重排进度，让碎片逐渐形成信息网格。'],zrender:['ZRENDER / 5.6.1','让变化，有数据依据。','点击条形对照原始 GLB 与网页 GLB 的文件体积。'],noto:['NOTO EMOJI / SVG','一个符号，帮内容开场。','编辑标题与图标尺寸，导出可复用的图文 SVG。']};
 function load(src){return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=reject;document.head.append(s);});}
 function download(name,content,type){const u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000);$('#status').textContent='已生成 '+name+'，请查看浏览器下载。';}
 function exportWith(label,fn){$('#export').hidden=false;$('#export').textContent=label;$('#export').onclick=fn;}
 const xml=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
 async function init(){
 const t=titles[tool];if(!t)throw Error('未知工具');$('#label').textContent=t[0];$('#title').textContent=t[1];$('#intro').textContent=t[2];
 if(tool==='motion'){
 await load('vendor/motion.js');stage.innerHTML='<article class="motion-card"><span>01 / INTRODUCE</span><b>MAKE IT<br>MEAN<br>SOMETHING.</b><span>动作，服务于理解。</span></article>';controls.innerHTML='<button id="play">重播入场</button><label>节奏<select id="ease"><option value="soft">柔和过渡</option><option value="linear">线性移动</option></select></label><label><input id="reduce" type="checkbox">减少动态</label>';let animation;$('#reduce').checked=matchMedia('(prefers-reduced-motion: reduce)').matches;const play=()=>{animation?.stop();const reduced=$('#reduce').checked;animation=Motion.animate('.motion-card',{opacity:[0,1],x:[-100,0],rotate:[-8,0]},{duration:reduced?0:.9,ease:$('#ease').value==='linear'?'linear':[.16,1,.3,1]});$('#status').textContent=reduced?'减少动态：直接呈现结果。':$('#ease').value==='linear'?'线性：匀速抵达。':'柔和：先快后慢，停留在结果。';};$('#play').onclick=play;$('#ease').onchange=play;$('#reduce').onchange=play;play();exportWith('导出配置 JSON',()=>download('motion-rhythm.json',JSON.stringify({trigger:'click',target:'.motion-card',keyframes:{opacity:[0,1],x:[-100,0],rotate:[-8,0]},options:{duration:$('#reduce').checked?0:.9,ease:$('#ease').value==='linear'?'linear':[.16,1,.3,1]}},null,2),'application/json'));
 } else if(tool==='paper'){
 await load('vendor/paper.js');stage.innerHTML='<canvas id="path-canvas" width="900" height="300" aria-label="曲线路径和观察点"></canvas>';controls.innerHTML='<label>路径曲率<input id="curve" type="range" min="0" max="100" value="60"></label><label>观察点进度<input id="travel" type="range" min="0" max="100" value="35"></label>';paper.setup($('#path-canvas'));const path=new paper.Path({strokeColor:'#d8e866',strokeWidth:4}),dot=new paper.Path.Circle({center:[0,0],radius:10,fillColor:'#f6f8ee'});function draw(){const y=+$('#curve').value;path.removeSegments();path.add(new paper.Segment([70,210],null,[180,-y*2]));path.add(new paper.Segment([830,90],[-180,y*2],null));dot.position=path.getPointAt(path.length*+$('#travel').value/100);paper.view.update();$('#status').textContent='曲率 '+y+' / 观察点 '+$('#travel').value+'%。路径仅说明运镜关系，不代表三维碰撞检测。';}$('#curve').oninput=draw;$('#travel').oninput=draw;draw();exportWith('导出 SVG',()=>download('camera-path.svg',paper.project.exportSVG({asString:true}),'image/svg+xml'));
 } else if(tool==='grapes'){
 const css=document.createElement('link');css.rel='stylesheet';css.href='vendor/grapes.min.css';document.head.append(css);await load('vendor/grapes.min.js');stage.classList.add('editor');const editor=grapesjs.init({container:'#stage',height:'430px',width:'auto',fromElement:false,storageManager:false,telemetry:false,noticeOnUnload:false,components:'<section class="hero"><small>STUDIO / PRODUCT STORY</small><h1>细节，让选择更清楚。</h1><p>双击这里，写下你的产品主张。</p><a href="#details">探索设计 →</a></section><section id="details"><h2>先让用户看懂，再邀请他们行动。</h2><p>这是一份可编辑的页面起点。</p></section>',style:'body{margin:0;font-family:Arial,sans-serif;background:#101811;color:#eef2e7}.hero{padding:55px 35px;background:#d8e866;color:#152012}.hero h1{font-size:42px;max-width:520px;line-height:1.2}small{letter-spacing:2px}a{display:inline-block;color:inherit;border:1px solid;padding:12px 20px;text-decoration:none}#details{padding:35px}'});editor.BlockManager.add('story-section',{label:'叙事段落',content:'<section style="padding:35px"><h2>故事的下一步</h2><p>给用户一个清楚的理由。</p></section>'});controls.innerHTML='<button id="add-section">添加叙事段落</button>';$('#add-section').onclick=()=>{editor.addComponents('<section style="padding:35px"><h2>新的章节</h2><p>双击编辑你的内容。</p></section>');$('#status').textContent='已添加段落，编辑后请导出保存。';};$('#status').textContent='编辑只保留在本次页面中；未自动发布。';exportWith('导出页面 HTML',()=>download('my-product-story.html','<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>产品叙事</title><style>'+editor.getCss()+'</style>'+editor.getHtml()+'</html>','text/html'));
 } else if(tool==='two'){
 await load('vendor/two.js');const two=new Two({type:Two.Types.svg,width:900,height:280}).appendTo(stage),shapes=[];for(let i=0;i<12;i++){const shape=two.makeRoundedRectangle(80+(i*173)%740,45+(i*83)%190,95,48,9);shape.fill=i%3===0?'#edf4c1':i%3===1?'#d8e866':'#7a9368';shape.noStroke();shapes.push({shape,from:[shape.position.x,shape.position.y],angle:(i%5-2)*.19});}controls.innerHTML='<label>重排进度<input id="layout" type="range" min="0" max="100" value="0"></label><button id="align">整齐排列</button><button id="scatter">返回散落</button>';function draw(){const p=+$('#layout').value/100;shapes.forEach(({shape,from,angle},i)=>{shape.position.set(from[0]+(205+i%4*165-from[0])*p,from[1]+(65+Math.floor(i/4)*75-from[1])*p);shape.rotation=angle*(1-p);});two.update();$('#status').textContent='重排 '+Math.round(p*100)+'%：保持同一组元素，改变组织方式。';}$('#layout').oninput=draw;$('#align').onclick=()=>{$('#layout').value=100;draw();};$('#scatter').onclick=()=>{$('#layout').value=0;draw();};draw();exportWith('导出 SVG',()=>download('layout-study.svg',two.renderer.domElement.outerHTML,'image/svg+xml'));
 } else if(tool==='zrender'){
 await load('vendor/zrender.js');stage.style.height='290px';const chart=zrender.init(stage,{renderer:'canvas'}),data=await fetch('../road-glide/assets/model-report.json').then(r=>r.json());let selected=1;controls.innerHTML='<button id="source">原始 GLB</button><button id="web">网页 GLB</button>';function draw(){chart.clear();const w=stage.clientWidth,max=data.sourceBytes;[['原始 GLB',data.sourceBytes],['网页 GLB',data.webBytes]].forEach(([name,value],i)=>{const y=65+i*105;chart.add(new zrender.Text({style:{x:25,y:y-25,text:name+' / '+(value/1e6).toFixed(2)+' MB',fill:'#edf2e7',font:'15px Arial'}}));const bar=new zrender.Rect({shape:{x:25,y,width:Math.max(15,(w-70)*value/max),height:42,r:5},style:{fill:i===selected?'#d8e866':'#71835e'}});bar.on('click',()=>{selected=i;draw();});chart.add(bar);});$('#source').setAttribute('aria-pressed',selected===0);$('#web').setAttribute('aria-pressed',selected===1);$('#status').textContent=(selected?'网页模型：':'原始模型：')+((selected?data.webBytes:data.sourceBytes)/1e6).toFixed(2)+' MB。文件减少 '+(100*(1-data.webBytes/data.sourceBytes)).toFixed(1)+'%；不等同于加载耗时减少。';}$('#source').onclick=()=>{selected=0;draw();};$('#web').onclick=()=>{selected=1;draw();};new ResizeObserver(()=>{chart.resize();draw();}).observe(stage);draw();exportWith('导出数据 JSON',()=>download('model-size-report.json',JSON.stringify(data,null,2),'application/json'));
 } else if(tool==='noto'){
 stage.innerHTML='<article class="emoji-card"><img src="vendor/noto-sparkles.svg" alt=""><div><small>A LITTLE MOMENT OF DELIGHT</small><h2 id="emoji-title">让好想法发光。</h2><p>留一点轻松，给重要的内容。</p></div></article>';controls.innerHTML='<label>标题<input id="headline" type="text" value="让好想法发光。" maxlength="18"></label><label>图标尺寸<input id="icon-size" type="range" min="40" max="140" value="80"></label>';$('#headline').oninput=()=>$('#emoji-title').textContent=$('#headline').value;$('#icon-size').oninput=()=>{stage.querySelector('img').style.width=$('#icon-size').value+'px';stage.querySelector('img').style.height=$('#icon-size').value+'px';};$('#status').textContent='Noto 官方 SVG；图标许可见 vendor/NOTO-SVG-LICENSE.txt。';exportWith('导出图文 SVG',async()=>{const svg=await fetch('vendor/noto-sparkles.svg').then(r=>r.text()),base64=btoa(unescape(encodeURIComponent(svg))),size=+$('#icon-size').value;download('noto-story-card.svg','<svg xmlns="http://www.w3.org/2000/svg" width="800" height="300"><rect width="800" height="300" fill="#1c281e"/><image href="data:image/svg+xml;base64,'+base64+'" x="50" y="'+(150-size/2)+'" width="'+size+'" height="'+size+'"/><text x="'+(80+size)+'" y="165" fill="#edf2e7" font-family="sans-serif" font-size="32">'+xml($('#headline').value)+'</text></svg>','image/svg+xml');});
 }
 }
 init().catch(e=>{$('#status').textContent='加载失败，请刷新重试。'+e.message;console.error(e);});
})();
